(()=>{
'use strict';
const $=s=>document.querySelector(s),view=$('#view');
const urlPath=p=>p.split('/').map(encodeURIComponent).join('/');
const state={route:'inicio',course:'piano',lesson:null,noteCategory:'Todas',search:'',labTab:'acordes',root:0,chord:'mayor',tempo:100,metronome:null,beat:0,ear:null,earScore:0,earCount:0,midi:[],theme:localStorage.getItem('astr4-theme')||'dark'};
const NOTES=['Do','Do♯','Re','Re♯','Mi','Fa','Fa♯','Sol','Sol♯','La','La♯','Si'];
const ENH={'Do♯':'Re♭','Re♯':'Mi♭','Fa♯':'Sol♭','Sol♯':'La♭','La♯':'Si♭'};
const CHORDS={mayor:[0,4,7],menor:[0,3,7],disminuido:[0,3,6],aumentado:[0,4,8],maj7:[0,4,7,11],'7':[0,4,7,10],m7:[0,3,7,10]};
const SCALES={ 'Mayor':[0,2,4,5,7,9,11],'Menor natural':[0,2,3,5,7,8,10],'Menor armónica':[0,2,3,5,7,8,11],'Pentatónica mayor':[0,2,4,7,9],'Pentatónica menor':[0,3,5,7,10],'Blues menor':[0,3,5,6,7,10]};
const PROGS=[{name:'Pop clásico',vibe:'Alegre / nostálgica',degrees:['I','V','vi','IV'],roots:[0,7,9,5],chords:['Do','Sol','Lam','Fa']},{name:'Pop melancólico',vibe:'Triste',degrees:['vi','IV','I','V'],roots:[9,5,0,7],chords:['Lam','Fa','Do','Sol']},{name:'ii–V–I',vibe:'Calmada / jazz',degrees:['ii','V','I'],roots:[2,7,0],chords:['Rem7','Sol7','Do maj7']},{name:'Trap / R&B',vibe:'Oscura',degrees:['i','VI','VII'],roots:[9,5,7],chords:['Lam','Fa','Sol']},{name:'Latina',vibe:'Dramática',degrees:['i','VII','VI','V'],roots:[9,7,5,4],chords:['Lam','Sol','Fa','Mi']}];
let db={completed:[],favorites:[],notes:[],quiz:{},streak:0,lastStudy:null,projects:[],practiceLog:[],practiceChecks:{},songs:[],weeklyPlan:{},challengeChecks:{},productionChecks:{},productionNotes:[],releaseData:{},createdAt:new Date().toISOString()};
try{const saved=JSON.parse(localStorage.getItem('astr4-data')||'null');if(saved&&typeof saved==='object')db={...db,...saved,projects:Array.isArray(saved.projects)?saved.projects:[],practiceLog:Array.isArray(saved.practiceLog)?saved.practiceLog:[],practiceChecks:saved.practiceChecks||{},songs:Array.isArray(saved.songs)?saved.songs:[],weeklyPlan:saved.weeklyPlan||{},challengeChecks:saved.challengeChecks||{},productionChecks:saved.productionChecks||{},productionNotes:Array.isArray(saved.productionNotes)?saved.productionNotes:[],releaseData:saved.releaseData||{}};}catch(e){}
const save=()=>localStorage.setItem('astr4-data',JSON.stringify(db));
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2400)}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function allLessons(){return [...ASTR4_DATA.piano.map((x,i)=>({id:'p'+i,course:'piano',title:x[0],desc:x[1],explain:x[2],example:x[3],apply:x[4],exercise:x[5],unit:x[6]||(i<4?'Fundamentos':i<6?'Escalas y tonalidad':i<11?'Acordes':'Armonía y composición')})),...ASTR4_DATA.production.map((x,i)=>({id:'m'+i,course:'production',title:x[0],desc:x[1],explain:x[2],example:x[3],apply:x[4],exercise:x[5],unit:x[6]||(i<3?'Fundamentos de producción':i<8?'Composición y armonía':i<15?'Ritmo y géneros':'Mezcla y flujo de trabajo')}))]}
const lessons=allLessons();
// Ampliación a 999 lecciones por academia: 499 itinerarios adicionales con objetivos y prácticas diferenciadas.
const EXTRA_TOPICS_PIANO=[
'Lectura en clave de sol','Lectura en clave de fa','Líneas adicionales','Figuras rítmicas','Silencios y duración','Puntillo y ligadura','Compases simples','Compases compuestos','Anacrusa y comienzo','Síncopas en piano','Tresillos y subdivisión','Alteraciones accidentales','Armaduras de clave','Enarmonía práctica','Intervalos melódicos','Intervalos armónicos','Inversiones de intervalos','Escala menor natural','Escala menor armónica','Escala menor melódica','Escalas pentatónicas','Escala blues','Modos griegos','Grados de la escala','Tonalidades vecinas','Círculo de quintas','Tríadas mayores','Tríadas menores','Acordes disminuidos','Acordes aumentados','Acordes suspendidos','Acordes de sexta','Acordes maj7','Acordes dominantes','Acordes m7','Acordes semidisminuidos','Novenas y extensiones','Inversiones de tríadas','Inversiones de séptimas','Posición fundamental','Voicings cerrados','Voicings abiertos','Conducción de voces','Notas comunes','Notas de paso','Retardos y apoyaturas','Anticipaciones','Pedal armónico','Cadencia auténtica','Cadencia plagal','Cadencia rota','Cadencia semicadencial','Funciones tonales','Dominantes secundarias','Intercambio modal','Modulación cercana','Armonización de melodías','Contramelodías','Diseño de motivos','Desarrollo motívico','Fraseo y respiración','Dinámica pianística','Articulación legato','Articulación staccato','Pedal de sustain','Coordinación de manos','Independencia de dedos','Digitación eficiente','Saltos y desplazamientos','Acompañamiento arpegiado','Patrones de mano izquierda','Acordes en bloque','Ritmos de acompañamiento','Lectura a primera vista','Memorización musical','Improvisación tonal','Improvisación modal','Transposición','Rearmonización','Piano pop','Piano romántico','Piano jazz','Piano neo-soul','Piano para baladas','Piano para reggaetón','Piano para composición','Análisis de canciones','Tensión y resolución','Registro y textura','Planificación de práctica'
]
const EXTRA_TOPICS_PROD=[
'Configuración de sesión','Plantillas de proyecto','Gestión de tempo','Cuantización MIDI','Swing y groove','Velocidad MIDI','Duración de notas MIDI','Edición de piano roll','Escalas en el piano roll','Acordes MIDI','Arpegios MIDI','Humanización MIDI','Capas de instrumentos','Selección de sonidos','Diseño de bajos','Subgrave y 808','Bombo y bajo','Caja y palmada','Hi-hats y rolls','Percusión latina','Dembow y variaciones','Patrones de trap','Ritmos R&B','Ritmos pop','Loops de cuatro compases','Loops de ocho compases','Transiciones','Risers y efectos','Impactos y fills','Automatización','Filtros y barridos','Síntesis sustractiva','Osciladores','Envolvente ADSR','LFO y modulación','Filtros resonantes','Unísono y detune','Capas de sintetizadores','Diseño de plucks','Diseño de pads','Diseño de leads','Texturas ambientales','Muestreo creativo','Edición de audio','Warping y time stretch','Pitch shifting','Vocal chops','Afinación vocal','Dobles vocales','Armonías vocales','Ad-libs','Comping vocal','EQ correctiva','EQ tonal','Filtros pasa altos','Enmascaramiento','Compresión vocal','Compresión paralela','Compresión sidechain','Saturación armónica','Distorsión controlada','Reverb por envíos','Delay rítmico','Pre-delay','Control de sibilancia','De-esser','Paneo y anchura','Fase y polaridad','Ganancia por etapas','Headroom','Medición de LUFS','Picos verdaderos','Limitación','Exportación de mezcla','Pre-master','Organización de stems','Referencias de mezcla','Balance estático','Automatización de mezcla','Arreglo por secciones','Contraste entre secciones','Construcción de estribillo','Drop y breakdown','Composición topline','Melodía vocal','Motivos repetitivos','Notas objetivo','Tensión melódica','Armonía modal','Rearmonización','Composición por emoción','Producción reggaetón','Producción trap','Producción pop urbano','Producción R&B','Producción afrobeat','Producción house','Producción lo-fi','Flujo de trabajo en Ableton'
]
function makeExtra(course, start, count){const bank=course==='piano'?EXTRA_TOPICS_PIANO:EXTRA_TOPICS_PROD;const out=[];for(let i=0;i<count;i++){const topic=bank[i%bank.length],variant=Math.floor(i/bank.length)+1;const title=variant===1?topic:`${topic}: aplicación ${variant}`;const unit=Math.floor(i/20)+26;const unitName=bank[(Math.floor(i/20)*20)%bank.length];const isP=course==='piano';const desc=isP?`Profundiza en ${topic.toLowerCase()} y llévalo al teclado mediante escucha, lectura y práctica deliberada.`:`Aplica ${topic.toLowerCase()} a un proyecto musical y comprende cómo influye en el resultado sonoro.`;const explain=isP?`${topic} se aprende relacionando el concepto escrito con su sonido y su posición en el teclado. Identifica primero los elementos que intervienen, observa sus relaciones y comprueba el resultado tocando despacio antes de aumentar la dificultad.`:`${topic} forma parte del flujo de producción. Antes de modificar parámetros, identifica qué problema o intención musical tienes; realiza un cambio cada vez, compara con el original y conserva la versión que mejor sirva a la canción.`;const example=isP?`En Do mayor, localiza las notas implicadas en ${topic.toLowerCase()}, tócalas por separado y después dentro de un contexto musical sencillo.`:`Abre una sesión de Ableton, crea una copia de seguridad del proyecto y prueba ${topic.toLowerCase()} en un fragmento de ocho compases para poder comparar A/B.`;const apply=isP?`Practica con metrónomo lento, mantén una digitación cómoda y escucha la estabilidad del pulso. Después transpón el ejercicio a otra tonalidad.`:`En producción, prioriza la intención y el contexto. Comprueba cómo convive con voz, bajo y percusión, y evita procesar por costumbre.`;const exercise=isP?`Crea un ejercicio de cuatro compases que utilice ${topic.toLowerCase()}. Grábalo, escúchalo y anota una mejora concreta.`:`Crea dos versiones del mismo loop: una sin el recurso y otra aplicando ${topic.toLowerCase()}. Compara claridad, energía y coherencia.`;out.push({id:(isP?'p':'m')+(start+i),course,title,desc,explain,example,apply,exercise,unit:`${String(unit).padStart(2,'0')} · ${unitName}`});}return out}
lessons.push(...makeExtra('piano',500,499),...makeExtra('production',500,499));
function go(route){state.route=route;state.lesson=null;document.querySelectorAll('.nav-group').forEach(g=>{g.classList.remove('open');g.querySelector('.nav-group-trigger')?.setAttribute('aria-expanded','false')});render();window.scrollTo({top:0,behavior:'smooth'});}
function header(title,sub=''){return `<div class="page-heading"><div class="eyebrow">${sub||'ASTR4 · MUSIC ACADEMY'}</div><div class="section-head"><h2>${title}</h2></div></div>`}
function card(icon,title,desc,route){return `<button class="card" data-go="${route}" style="text-align:left;color:inherit;cursor:pointer"><span class="card-icon">${icon}</span><h3>${title}</h3><p>${desc}</p></button>`}
function courseLessons(course){return lessons.filter(l=>l.course===course)}
function home(){let done=db.completed.length,total=lessons.length,pct=Math.round(done/total*100);return `<section class="hero"><img class="hero-wave" src="assets/onda-astr4.png" alt="Onda sonora luminosa violeta"><div class="hero-inner"><div class="eyebrow">ACADEMIA MUSICAL · 1.998 LECCIONES</div><h1>Aprende.<br>Comprende.<br><span style="color:#d7baff">Crea.</span></h1><p>Teoría musical, piano y producción en un entorno diseñado para transformar conocimiento en música.</p><div class="hero-actions"><button class="btn" data-go="academia">Explorar academias ↗</button><button class="btn secondary" data-go="laboratorio">Abrir laboratorio</button></div><div class="stat-row"><div class="stat"><strong>${done}</strong><span>Lecciones hechas</span></div><div class="stat"><strong>${db.favorites.length}</strong><span>Favoritos</span></div><div class="stat"><strong>${pct}%</strong><span>Progreso global</span></div></div><div class="progress"><i style="width:${pct}%"></i></div></div></section>
${header('Explora ASTR4','APRENDE A TU RITMO')}<div class="grid">${card('◈','Mi estudio','Organiza proyectos, sesiones y tu camino como artista-productor.','estudio')}${card('♫','Cuaderno creativo','Guarda letras, conceptos, estructuras y canciones.','cancionero')}${card('◷','Plan de práctica','Organiza tu semana entre piano, oído y producción.','planificador')}${card('✦','Retos creativos','Convierte lo que aprendes en canciones y demos.','retos')}${card('▤','Academia','Dos academias completas de 999 lecciones cada una.','academia')}${card('✧','Actividades','Retos y prácticas musicales interactivas.','actividades')}${card('▧','Apuntes','Fichas visuales para consultar rápidamente.','apuntes')}${card('⌘','Laboratorio','Construye acordes, escalas y progresiones.','laboratorio')}${card('♫','Oído musical','Entrena intervalos y reconocimiento armónico.','oido')}${card('⌕','Diccionario','Encuentra conceptos musicales al instante.','diccionario')}${card('✎','Composición','Ideas y ejercicios para crear música.','composicion')}${card('◷','Herramientas','Metrónomo, afinador y biblioteca MIDI.','herramientas')}${card('▣','Material original','Tus PDF, ejercicios HTML y recursos.','recursos')}</div>
${header('Retoma tu aprendizaje')}<div class="card wide"><div class="eyebrow">${db.lastStudy?'ÚLTIMA ACTIVIDAD':'PARA EMPEZAR'}</div><h3>${db.lastStudy?esc(db.lastStudy):'El mapa del teclado'}</h3><p>Avanza con una lección breve y aplica lo aprendido en el piano o en tu DAW.</p><button class="btn small" style="margin-top:12px" data-action="continue">Abrir lección</button></div>`}
function academy(){return `${header('Academia','DOS RUTAS · APRENDIZAJE PROGRESIVO')}<p class="tiny">Las lecciones están organizadas para avanzar desde los fundamentos. Cada una incluye explicación, ejemplo aplicado, ejercicio y una pregunta de comprobación.</p><div class="grid"><button class="card" data-action="course" data-course="piano" style="text-align:left;color:inherit"><span class="card-icon">♬</span><h3>Teoría musical y piano</h3><p>Notas, escalas, intervalos, acordes, armonía y composición desde el teclado.</p><div class="progress"><i style="width:${courseLessons('piano').filter(l=>db.completed.includes(l.id)).length/courseLessons('piano').length*100}%"></i></div><p style="margin-top:8px">${courseLessons('piano').filter(l=>db.completed.includes(l.id)).length}/${courseLessons('piano').length} lecciones completadas</p></button><button class="card" data-action="course" data-course="production" style="text-align:left;color:inherit"><span class="card-icon">◉</span><h3>Producción musical</h3><p>Armonía aplicada, melodías, ritmos, géneros, loops y fundamentos de mezcla.</p><div class="progress"><i style="width:${courseLessons('production').filter(l=>db.completed.includes(l.id)).length/courseLessons('production').length*100}%"></i></div><p style="margin-top:8px">${courseLessons('production').filter(l=>db.completed.includes(l.id)).length}/${courseLessons('production').length} lecciones completadas</p></button></div><div class="section-head"><h2>Recursos de aprendizaje</h2></div><div class="list"><button class="list-item" data-go="oido"><span class="num">♫</span><span><strong>Entrenamiento auditivo</strong><small>Reconoce intervalos y acordes</small></span><span class="chev">›</span></button><button class="list-item" data-go="composicion"><span class="num">✎</span><span><strong>Academia de composición</strong><small>Aplica la teoría creando ideas</small></span><span class="chev">›</span></button><button class="list-item" data-go="diccionario"><span class="num">A–Z</span><span><strong>Diccionario musical</strong><small>Consulta términos y conceptos</small></span><span class="chev">›</span></button></div>`}

function studio(){
 const projects=db.projects||[], checks=db.practiceChecks||{}, today=new Date().toISOString().slice(0,10), done=checks[today]||{};
 const tasks=[['piano','Piano y técnica','Escalas, acordes y coordinación'],['ear','Oído musical','Intervalos, acordes y ritmo'],['writing','Composición','Melodía, progresión o letra'],['production','Producción en Ableton','Baterías, sonidos y arreglos'],['critical','Escucha crítica','Comparar con referencias']];
 const mins=(db.practiceLog||[]).filter(x=>x.date===today).reduce((a,x)=>a+(+x.minutes||0),0);
 const roadmap=[['01','Fundamentos','Ritmo, tonalidad, intervalos, acordes y teclado.'],['02','Composición','Melodías, progresiones, bajos y estructuras.'],['03','Ableton Live','MIDI, audio, baterías, síntesis y arreglos.'],['04','Mezcla','Ganancia, EQ, compresión, espacio y referencias.'],['05','Identidad artística','Voz, letras, interpretación y sonido propio.'],['06','Lanzamiento','Canciones terminadas, portada y publicación.']];
 return `${header('Mi estudio','TU ESPACIO DE ARTISTA Y PRODUCTOR')}<section class="studio-hero"><div class="studio-orb"></div><div class="eyebrow">ARTISTA · PRODUCTOR · APRENDIZ</div><h1>De una idea<br><span>a una canción.</span></h1><p>Organiza tus proyectos, entrena tus habilidades y lleva cada idea desde el primer acorde hasta una producción terminada.</p><div class="studio-actions"><button class="btn" data-go="laboratorio">Abrir laboratorio</button><button class="btn secondary" data-go="composicion">Componer</button><button class="btn ghost" data-go="produccion">Sala de producción</button></div><div class="studio-stats"><div><b>${projects.length}</b><small>Proyectos</small></div><div><b>${mins}</b><small>Minutos hoy</small></div><div><b>${(db.practiceLog||[]).length}</b><small>Sesiones</small></div></div></section><div class="studio-grid"><main><section class="studio-panel"><div class="studio-heading"><div><div class="eyebrow">TU MÚSICA</div><h2>Proyectos musicales</h2></div><span class="studio-chip">${projects.length} guardados</span></div><form id="studio-project-form"><div class="studio-form-title"><span>＋</span><div><b>Crear proyecto</b><small>Guarda la información esencial de tu canción.</small></div></div><label>Nombre provisional</label><input class="studio-input" name="name" maxlength="70" placeholder="Ej. Lo que queda de nosotros" required><div class="studio-fields"><div><label>Estilo</label><select class="studio-input" name="style"><option>Reggaetón melódico</option><option>Pop urbano</option><option>Trap / R&B</option><option>Afrobeat</option><option>Dancehall</option><option>Pop</option><option>Otro</option></select></div><div><label>Ambiente</label><select class="studio-input" name="mood"><option>Melancólico</option><option>Nostálgico</option><option>Oscuro</option><option>Esperanzador</option><option>Enérgico</option><option>Romántico</option></select></div><div><label>Tonalidad</label><select class="studio-input" name="key">${NOTES.map(n=>`<option>${n}</option>`).join('')}</select></div><div><label>Tempo · BPM</label><input class="studio-input" name="bpm" type="number" min="40" max="220" value="95"></div></div><label>Letra, concepto y notas de producción</label><textarea class="studio-input" name="notes" rows="4" placeholder="Idea, frase vocal, progresión, referencias sonoras…"></textarea><button class="btn studio-save" type="submit">Guardar proyecto ↗</button></form></section><section class="studio-project-list"><div class="studio-heading"><div><div class="eyebrow">EN DESARROLLO</div><h2>Tus canciones</h2></div></div>${projects.length?projects.map(p=>`<article class="studio-project"><div class="studio-project-top"><span class="studio-chip">${esc(p.style||'Proyecto')}</span><small>${p.created?new Date(p.created).toLocaleDateString('es-ES'):''}</small></div><h3>${esc(p.name)}</h3><div class="studio-meta"><span>${esc(p.key||'—')}</span><span>${esc(String(p.bpm||'—'))} BPM</span><span>${esc(p.mood||'')}</span></div>${p.notes?`<p>${esc(p.notes)}</p>`:''}<button class="btn secondary small" data-action="studio-delete" data-id="${p.id}">Eliminar proyecto</button></article>`).join(''):'<div class="studio-empty"><b>Tu siguiente canción empieza aquí.</b><p>Crea un proyecto para guardar ideas, tonalidad, tempo y notas.</p></div>'}</section><section class="studio-panel"><div class="studio-heading"><div><div class="eyebrow">CONSTANCIA SIN PRESIÓN</div><h2>Práctica de hoy</h2></div><span class="studio-chip">${tasks.filter(t=>done[t[0]]).length}/5</span></div><p class="studio-muted">Marca lo que hayas trabajado. Una sesión corta y concentrada también cuenta.</p>${tasks.map(t=>`<label class="studio-task"><input type="checkbox" data-studio-task="${t[0]}" ${done[t[0]]?'checked':''}><span class="studio-check"></span><span><b>${t[1]}</b><small>${t[2]}</small></span></label>`).join('')}<div class="studio-log"><label for="studio-minutes">Minutos de práctica</label><input id="studio-minutes" class="studio-input" type="number" min="1" max="600" value="30"><button class="btn small" data-action="studio-log">Registrar sesión</button></div></section></main><aside><section class="studio-panel"><div class="eyebrow">FLUJO DE TRABAJO</div><h2>Una sesión en Ableton</h2><p class="studio-muted">Un orden práctico para no perderte al producir.</p><ol class="studio-flow">${[['Captura la idea','Tempo, tonalidad y emoción.'],['Armonía y melodía','Progresión, motivo y variaciones.'],['Ritmo y groove','Kick, clap, hats y percusión.'],['Arreglo','Intro, verso, pre, estribillo y puente.'],['Producción y mezcla','Sonidos, balances y espacio.'],['Exporta y revisa','Escucha fuera del estudio y toma notas.']].map((x,i)=>`<li><i>${String(i+1).padStart(2,'0')}</i><span><b>${x[0]}</b><small>${x[1]}</small></span></li>`).join('')}</ol><button class="btn secondary studio-wide" data-go="curso-production">Estudiar producción</button></section><section class="studio-panel"><div class="eyebrow">TU CAMINO</div><h2>De aprender a publicar</h2><div class="studio-roadmap">${roadmap.map(x=>`<div><i>${x[0]}</i><span><b>${x[1]}</b><small>${x[2]}</small></span></div>`).join('')}</div></section><section class="studio-panel"><div class="eyebrow">ATAJOS</div><h2>Herramientas creativas</h2><button class="list-item" data-go="midi"><span class="num">MIDI</span><span><strong>Progresiones MIDI</strong><small>Ideas para Ableton Live</small></span><span class="chev">›</span></button><button class="list-item" data-go="laboratorio"><span class="num">♫</span><span><strong>Laboratorio armónico</strong><small>Escucha acordes y escalas</small></span><span class="chev">›</span></button><button class="list-item" data-go="produccion"><span class="num">MIX</span><span><strong>Sala de producción</strong><small>Grabación, mezcla y lanzamiento</small></span><span class="chev">›</span></button><button class="list-item" data-go="oido"><span class="num">耳</span><span><strong>Entrenamiento auditivo</strong><small>Desarrolla tu oído</small></span><span class="chev">›</span></button></section></aside></div>`;
}

function songbook(){
 const songs=db.songs||[];const active=songs.filter(x=>x.status!=='Terminada').length;
 const status=['Idea','Escribiendo','Preproducción','Producción','Mezcla','Terminada'];
 return `${header('Cuaderno creativo','LETRAS · CANCIONES · IDENTIDAD')}<section class="upgrade-hero"><div><span class="eyebrow">TU CATÁLOGO MUSICAL</span><h1>Que ninguna<br><em>idea se pierda.</em></h1><p>Guarda conceptos, letras, estructuras y decisiones creativas. Cada canción puede crecer sin depender de notas sueltas.</p><div class="upgrade-kpis"><div><b>${songs.length}</b><small>Canciones guardadas</small></div><div><b>${active}</b><small>En desarrollo</small></div><div><b>${songs.filter(x=>x.status==='Terminada').length}</b><small>Terminadas</small></div></div></div><div class="upgrade-orbit">✦</div></section>
 <section class="upgrade-panel"><div class="upgrade-title"><div><span class="eyebrow">NUEVA CREACIÓN</span><h2>Registrar canción</h2></div><span class="upgrade-tag">CUADERNO ASTR4</span></div><form id="song-form" class="upgrade-form"><div class="upgrade-two"><label>Título provisional<input name="title" maxlength="80" placeholder="Nombre de la canción" required></label><label>Estado<select name="status">${status.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Estilo musical<select name="genre"><option>Reggaetón melódico</option><option>Pop urbano</option><option>Trap / R&B</option><option>Afrobeat</option><option>Pop</option><option>Otro</option></select></label><label>Emoción principal<select name="mood"><option>Melancolía</option><option>Nostalgia</option><option>Desamor</option><option>Esperanza</option><option>Confianza</option><option>Euforia</option><option>Oscuridad</option></select></label><label>Tonalidad<input name="key" maxlength="12" placeholder="Ej. La menor"></label><label>Tempo (BPM)<input name="bpm" type="number" min="40" max="220" value="95"></label></div><label>Concepto de la canción<textarea name="concept" rows="2" placeholder="¿Qué quieres contar? ¿Cuál es la idea central?"></textarea></label><label>Letra / frases / melodía vocal<textarea name="lyrics" rows="8" placeholder="Escribe aquí tus versos, estribillo, frases sueltas o ideas de melodía…"></textarea></label><label>Estructura prevista<input name="structure" placeholder="Intro · Verso · Pre-estribillo · Estribillo · Verso · Puente"></label><label>Notas de producción y referencias<textarea name="production" rows="3" placeholder="Sonidos, instrumentos, referencias, tipo de batería, ambiente…"></textarea></label><button class="btn" type="submit">Guardar canción ↗</button></form></section>
 <section class="upgrade-panel"><div class="upgrade-title"><div><span class="eyebrow">ARCHIVO PERSONAL</span><h2>Tus canciones</h2></div><span class="upgrade-tag">${songs.length} REGISTROS</span></div>${songs.length?songs.map(x=>`<article class="song-card"><div class="song-card-head"><div><span class="upgrade-tag">${esc(x.status||'Idea')}</span><h3>${esc(x.title)}</h3></div><button class="mini-danger" data-action="song-delete" data-id="${esc(x.id)}" aria-label="Eliminar canción">×</button></div><div class="song-meta"><span>${esc(x.genre||'')}</span><span>${esc(x.mood||'')}</span><span>${esc(x.key||'Sin tonalidad')}</span><span>${esc(String(x.bpm||'—'))} BPM</span></div>${x.concept?`<p><b>Concepto:</b> ${esc(x.concept)}</p>`:''}${x.lyrics?`<details class="song-details"><summary>Ver letra e ideas</summary><pre>${esc(x.lyrics)}</pre></details>`:''}${x.structure?`<p class="song-line"><b>Estructura:</b> ${esc(x.structure)}</p>`:''}${x.production?`<details class="song-details"><summary>Notas de producción</summary><p>${esc(x.production)}</p></details>`:''}<div class="song-edit-row"><label>Actualizar estado<select data-song-status="${esc(x.id)}">${status.map(v=>`<option ${v===(x.status||'Idea')?'selected':''}>${v}</option>`).join('')}</select></label><small>Guardada ${x.created?new Date(x.created).toLocaleDateString('es-ES'):''}</small></div></article>`).join(''):'<div class="upgrade-empty"><b>Aún no has guardado canciones.</b><p>Empieza con una frase, un concepto o una melodía. No hace falta tenerlo todo decidido.</p></div>'}</section>`;
}
function planner(){
 const days=[['lun','Lunes'],['mar','Martes'],['mie','Miércoles'],['jue','Jueves'],['vie','Viernes'],['sab','Sábado'],['dom','Domingo']];
 const slots=[['piano','Piano y teoría','20–30 min'],['ear','Entrenamiento auditivo','10–15 min'],['write','Composición y letras','20–30 min'],['ableton','Producción en Ableton','30–45 min'],['review','Escucha crítica','10 min']];const plan=db.weeklyPlan||{};let total=0,done=0;days.forEach(([d])=>slots.forEach(([k])=>{total++;if(plan[d]?.[k])done++}));
 return `${header('Plan de práctica','ORGANIZA TU SEMANA MUSICAL')}<section class="upgrade-hero planner-hero"><div><span class="eyebrow">CONSTANCIA CON INTENCIÓN</span><h1>Una semana<br><em>mejor aprovechada.</em></h1><p>Distribuye el trabajo entre piano, oído, composición y producción. Marca cada bloque al terminarlo y ajusta la carga a tu tiempo real.</p><div class="upgrade-kpis"><div><b>${done}/${total}</b><small>Bloques completados</small></div><div><b>${Math.round(done/total*100)}%</b><small>Semana completada</small></div><div><b>${days.filter(([d])=>slots.some(([k])=>plan[d]?.[k])).length}</b><small>Días con práctica</small></div></div><div class="upgrade-progress"><i style="width:${done/total*100}%"></i></div></div></section><div class="planner-tip"><b>Una buena sesión tiene un objetivo.</b><span>No necesitas completar todos los bloques todos los días. Prioriza calidad, escucha y descanso.</span></div><div class="week-grid">${days.map(([d,name])=>{let n=slots.filter(([k])=>plan[d]?.[k]).length;return `<section class="week-day"><div class="week-day-head"><h3>${name}</h3><span>${n}/5</span></div>${slots.map(([k,label,time])=>`<label class="plan-task"><input type="checkbox" data-plan-day="${d}" data-plan-task="${k}" ${plan[d]?.[k]?'checked':''}><span class="plan-check"></span><span><b>${label}</b><small>${time}</small></span></label>`).join('')}</section>`}).join('')}</div><div class="upgrade-panel"><div class="upgrade-title"><div><span class="eyebrow">RECOMENDACIÓN DE SESIÓN</span><h2>Orden sugerido</h2></div></div><div class="session-steps">${[['01','Calienta','5 minutos de teclado o ritmo sencillo.'],['02','Aprende','Trabaja una lección concreta de la academia.'],['03','Aplica','Convierte el concepto en una melodía, acorde o loop.'],['04','Escucha','Graba una toma y apunta una mejora específica.']].map(a=>`<div><i>${a[0]}</i><span><b>${a[1]}</b><small>${a[2]}</small></span></div>`).join('')}</div></div>`;
}
function challenges(){
 const items=[['finish-loop','Crear un loop de 8 compases','Construye una idea con batería, bajo y armonía.'],['write-hook','Escribir un estribillo','Desarrolla una frase central y una melodía memorable.'],['record-vocal','Grabar una toma vocal','Haz una toma completa y detecta qué mejorar.'],['mix-reference','Analizar una referencia','Escucha una canción y anota balance, espacio y estructura.'],['learn-chords','Aprender una progresión','Tócala en el teclado y transpórtala a otra tonalidad.'],['arrange','Terminar un arreglo','Organiza intro, verso, estribillo y cierre.'],['export-demo','Exportar una demo','Guarda una versión escuchable de tu canción.']];let checks=db.challengeChecks||{},n=items.filter(x=>checks[x[0]]).length;
 return `${header('Retos creativos','OBJETIVOS QUE TE HACEN AVANZAR')}<section class="upgrade-hero challenge-hero"><div><span class="eyebrow">MENOS TEORÍA SIN APLICAR · MÁS MÚSICA TERMINADA</span><h1>Convierte el<br><em>aprendizaje en obra.</em></h1><p>Estos retos conectan lo que estudias con resultados reales. Puedes completarlos a tu ritmo y reiniciarlos cuando quieras.</p><div class="upgrade-kpis"><div><b>${n}/${items.length}</b><small>Retos completados</small></div><div><b>${Math.round(n/items.length*100)}%</b><small>Progreso</small></div><div><b>${items.length-n}</b><small>Pendientes</small></div></div><div class="upgrade-progress"><i style="width:${n/items.length*100}%"></i></div></div></section><div class="challenge-list">${items.map((x,i)=>`<label class="challenge-item ${checks[x[0]]?'is-done':''}"><input type="checkbox" data-challenge="${x[0]}" ${checks[x[0]]?'checked':''}><span class="challenge-number">${String(i+1).padStart(2,'0')}</span><span class="challenge-copy"><b>${x[1]}</b><small>${x[2]}</small></span><span class="challenge-state">${checks[x[0]]?'✓':'＋'}</span></label>`).join('')}</div><div class="upgrade-panel"><div class="eyebrow">REGLA ASTR4</div><h2>Termina más ideas de las que empiezas.</h2><p class="studio-muted">No midas tu avance solo por los plugins que conoces o las horas que pasas delante del DAW. Mídelo también por las canciones, loops y melodías que consigues terminar.</p><button class="btn secondary" data-go="estudio">Volver a Mi estudio</button></div>`;
}

function coursePage(course){let arr=courseLessons(course),name=course==='piano'?'Teoría musical y piano':'Producción musical';let groups={};arr.forEach(l=>(groups[l.unit]??=[]).push(l));let done=arr.filter(l=>db.completed.includes(l.id)).length;return `<button class="back" data-go="academia">← Volver a la academia</button>${header(name,course==='piano'?'RUTA 1 · 999 LECCIONES':'RUTA 2 · 999 LECCIONES')}<div class="card"><div class="eyebrow">TU PROGRESO</div><h3>${done} de 999 lecciones completadas</h3><div class="progress"><i style="width:${done/999*100}%"></i></div><p class="tiny" style="margin-top:9px">999 lecciones · 50 bloques de aprendizaje</p></div><label class="field-label" for="course-search">Buscar entre las 999 lecciones</label><input class="input" id="course-search" type="search" placeholder="Ej. inversiones, melodías, compresión…"><div id="course-groups">${Object.entries(groups).map(([unit,ls],gi)=>`<details class="course-unit" ${gi===0?'open':''}><summary><span><strong>${esc(unit)}</strong><small>${ls.length} lecciones · ${ls.filter(l=>db.completed.includes(l.id)).length} completadas</small></span><span class="pill">${ls.filter(l=>db.completed.includes(l.id)).length}/${ls.length}</span></summary><div class="list">${ls.map(l=>`<button class="list-item" data-lesson="${l.id}" data-course-title="${esc((l.title+' '+l.desc).toLowerCase())}"><span class="num">${db.completed.includes(l.id)?'✓':String(arr.indexOf(l)+1).padStart(3,'0')}</span><span><strong>${esc(l.title)}</strong><small>${esc(l.desc)}</small></span><span class="chev">›</span></button>`).join('')}</div></details>`).join('')}</div><div class="callout" style="margin-top:16px">Las 999 lecciones están disponibles en esta academia. Cada ficha incluye explicación, ejemplo aplicado, relación práctica y ejercicio. El progreso se conserva en este dispositivo.</div>`}
function lessonPage(l){db.lastStudy=l.title;save();let idx=lessons.findIndex(x=>x.id===l.id),isDone=db.completed.includes(l.id);const qp=[
 ['¿Dónde se localiza el Do en el teclado?',['A la izquierda del grupo de dos negras','A la derecha del grupo de tres negras','Entre dos teclas negras','En las teclas negras'],0],
 ['¿Cuántas posiciones tiene el ciclo cromático?',['7','8','12','14'],2],
 ['¿A cuántos semitonos equivale un tono?',['1','2','3','4'],1],
 ['¿Qué hace un sostenido?',['Baja un semitono','Sube un semitono','Sube un tono','No altera la nota'],1],
 ['¿Cuál es la fórmula de la escala mayor?',['T–S–T–T–S–T–T','T–T–S–T–T–T–S','T–S–T–T–T–S–T','S–T–T–S–T–T–T'],1],
 ['¿Qué notas forman La menor natural?',['La–Si–Do–Re–Mi–Fa–Sol','La–Si–Do♯–Re–Mi–Fa♯–Sol♯','La–Do–Mi–Sol','La–Si–Re–Mi–Fa–Sol–La'],0],
 ['¿Qué acorde corresponde al grado I de Do mayor?',['Re menor','Sol mayor','Do mayor','Si disminuido'],2],
 ['¿Qué distancias forman una tríada mayor?',['0–3–7','0–4–7','0–3–6','0–4–8'],1],
 ['¿Qué distancias forman una tríada menor?',['0–3–7','0–4–7','0–4–8','0–2–7'],0],
 ['¿Qué nota queda en el bajo en primera inversión?',['Fundamental','Quinta','Tercera','Séptima'],2],
 ['¿Qué nota añade Do maj7 a Do–Mi–Sol?',['Si','Si♭','La','Re'],0],
 ['¿Qué tonalidad está una quinta por encima de Do?',['Fa','Re','La','Sol'],3],
 ['¿Qué función suele generar tensión antes de volver a la tónica?',['Tónica','Dominante','Subdominante','Medianta'],1],
 ['¿Qué movimiento suele producir una resolución fuerte?',['I–IV','IV–ii','V–I','I–V'],2],
 ['¿Qué representa I–V–vi–IV en Do mayor?',['Do–Sol–Lam–Fa','Do–Fa–Sol–Lam','Lam–Fa–Do–Sol','Do–Mi–Sol–Fa'],0],
 ['¿Qué busca la conducción de voces?',['Aumentar siempre los saltos','Mover las voces de forma fluida','Eliminar notas comunes','Duplicar todas las notas'],1],
 ['¿Cuántos pulsos de negra tiene un compás 4/4?',['2','3','4','8'],2],
 ['¿Qué es un arpegio?',['Un acorde invertido','Notas de un acorde sucesivas','Una escala cromática','Un patrón de batería'],1],
 ['¿Qué hace una nota de paso?',['Conecta notas estructurales','Sustituye la tonalidad','Cambia el tempo','Duplica el bajo'],0],
 ['¿Qué ayuda a dar identidad a una frase?',['Solo notas rápidas','Motivo, repetición y variación','Eliminar los silencios','Usar siempre ocho notas'],1]
 ];const qm=[
 ['¿Qué representa el piano roll?',['El volumen de pista','Altura en vertical y tiempo en horizontal','La afinación del master','La forma de onda'],1],
 ['¿Qué define una tonalidad?',['Solo el tempo','Un centro tonal y un conjunto de notas','El volumen final','El tipo de compresor'],1],
 ['¿Qué describe I–V–vi–IV?',['Una secuencia de grados','Una escala menor armónica','Un patrón de batería','Una cadena de efectos'],0],
 ['¿Qué nota es un punto de partida habitual para el bajo?',['La sensible','La fundamental del acorde','La novena siempre','Una nota aleatoria'],1],
 ['¿Qué notas suelen sentirse estables en tiempos importantes?',['Notas ajenas al acorde','Notas del acorde','Solo cromatismos','Solo silencios'],1],
 ['¿Qué recurso puede contribuir a un carácter nostálgico?',['Movimiento descendente','Solo tempos rápidos','Eliminar la melodía','Usar únicamente notas graves'],0],
 ['¿Qué es el ritmo armónico?',['La velocidad del metrónomo','La frecuencia con la que cambian los acordes','La duración de una reverb','El patrón del hi-hat'],1],
 ['¿Qué busca un voicing abierto?',['Amontonar notas','Separar notas entre registros','Eliminar la fundamental siempre','Duplicar el tempo'],1],
 ['¿Qué hace que una progresión no determine por sí sola el género?',['El género depende también del ritmo, timbres y fraseo','Las progresiones no tienen acordes','El tempo no importa','La melodía no existe'],0],
 ['¿Qué puede aportar una nota pedal?',['Un punto de continuidad bajo la armonía cambiante','Un cambio de compás','Un efecto de reverb','Una compresión'],0],
 ['¿Qué es una extensión armónica?',['Una nota añadida como 9, 11 o 13','Un cambio de BPM','Una automatización de volumen','Un silencio'],0],
 ['¿Qué ayuda a evitar monotonía en un loop?',['Repetir sin cambios','Pequeñas variaciones y transiciones','Añadir todas las pistas','Subir el master'],1],
 ['¿Qué es una síncopa?',['Un acento desplazado a una parte débil','Un cambio de tonalidad','Un tipo de escala','Un compresor'],0],
 ['¿Cuántos pasos de semicorchea hay en un compás 4/4?',['8','12','16','32'],2],
 ['¿Qué zona suele aportar peso a una mezcla?',['Graves','Medios-altos','Agudos extremos','Solo el aire'],0],
 ['¿Qué es el clipping digital?',['Una señal por encima del máximo representable','Un tipo de reverb','Una técnica de paneo','Un patrón MIDI'],0],
 ['¿Qué controla el umbral de un compresor?',['El nivel a partir del cual actúa','La afinación','La panorámica','El tempo'],0],
 ['¿Qué controla el decay de una reverb?',['La duración de la cola','El tono fundamental','El ataque del bombo','El compás'],0],
 ['¿Qué puede crear contraste entre verso y estribillo?',['Densidad, registro y energía','Solo el nombre de la sección','Mantener absolutamente todo igual','Eliminar la armonía'],0],
 ['¿Qué almacena un archivo MIDI?',['Audio grabado','Eventos como notas, duración y velocidad','La mezcla estéreo','El sonido del piano'],1]
 ];let quiz=(l.course==='piano'?qp:qm)[idx%20],q=quiz[0],opts=quiz[1],correct=quiz[2];return `<button class="back" data-action="back-course" data-course="${l.course}">← Volver al curso</button><div class="eyebrow">${l.course==='piano'?'TEORÍA MUSICAL Y PIANO':'PRODUCCIÓN MUSICAL'} · LECCIÓN ${idx+1}</div><h1 style="font:700 27px 'Space Grotesk';letter-spacing:-.04em;margin:9px 0">${esc(l.title)}</h1><p class="muted" style="font-size:13px;line-height:1.5">${esc(l.desc)}</p><div class="card lesson-content"><span class="pill">IDEA PRINCIPAL</span><p>${esc(l.explain)}</p><h3>Ejemplo práctico</h3><div class="callout">${esc(l.example)}</div><h3>Aplicación musical</h3><p>${esc(l.apply)}</p><h3>Practica por tu cuenta</h3><p>${esc(l.exercise)}</p><h3>Comprueba lo aprendido</h3><p>${q}</p><div class="answer-grid">${opts.map((o,i)=>`<button class="answer" data-quiz="${i}" data-correct="${correct}">${o}</button>`).join('')}</div><p class="tiny" id="quiz-feedback" aria-live="polite">Selecciona una respuesta para comprobarla.</p><div class="divider"></div><button class="btn ${isDone?'secondary':''}" data-action="complete" data-id="${l.id}">${isDone?'✓ Lección completada':'Marcar como completada'}</button><button class="btn ghost small" style="margin-left:6px" data-action="favorite" data-id="${l.id}">${db.favorites.includes(l.id)?'★ Guardado':'☆ Guardar'}</button></div><div class="control-row" style="justify-content:space-between;margin-top:15px"><button class="btn ghost small" data-lesson="${lessons[idx-1]?.id||''}" ${idx===0?'disabled':''}>← Anterior</button><button class="btn small" data-lesson="${lessons[idx+1]?.id||''}" ${idx===lessons.length-1?'disabled':''}>Siguiente →</button></div>`}
function noteVisual(n){
 const title=n.title;
 if(title==='Las 12 notas del piano') return `<div class="note-visual chromatic-visual" aria-label="Las doce notas cromáticas">${['Do','Do♯','Re','Re♯','Mi','Fa','Fa♯','Sol','Sol♯','La','La♯','Si'].map((x,i)=>`<span class="note-chip ${[1,3,6,8,10].includes(i)?'accidental':''}"><b>${x}</b><small>${i+1}</small></span>`).join('')}</div><div class="visual-caption"><span class="visual-dot"></span> 12 posiciones · ciclo cromático</div>`;
 if(title==='Fórmulas de tríadas') return `<div class="note-visual triad-visual">${[['Mayor','0 · 4 · 7'],['Menor','0 · 3 · 7'],['Disminuida','0 · 3 · 6'],['Aumentada','0 · 4 · 8']].map((x,i)=>`<div class="triad-item"><span class="triad-mark">${['M','m','°','+'][i]}</span><span><b>${x[0]}</b><small>${x[1]} semitonos</small></span></div>`).join('')}</div>`;
 if(title==='Acordes diatónicos de Do mayor') return `<div class="note-visual chord-row">${[['I','Do','M'],['ii','Rem','m'],['iii','Mim','m'],['IV','Fa','M'],['V','Sol','M'],['vi','Lam','m'],['vii°','Si','°']].map(x=>`<div class="chord-token"><small>${x[0]}</small><b>${x[1]}</b><em>${x[2]}</em></div>`).join('')}</div>`;
 if(title==='Progresiones y carácter') return `<div class="note-visual progression-visual">${[['POP','I – V – vi – IV'],['JAZZ','ii – V – I'],['BLUES','I⁷ – IV⁷ – V⁷'],['TRAP / R&B','i – VI – VII']].map(x=>`<div class="progression-line"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div>`;
 if(title==='Funciones armónicas') return `<div class="note-visual function-visual"><div><span class="function-icon">Ⅰ</span><b>Tónica</b><small>Reposo</small></div><i>→</i><div><span class="function-icon">Ⅳ</span><b>Subdominante</b><small>Movimiento</small></div><i>→</i><div><span class="function-icon">Ⅴ</span><b>Dominante</b><small>Tensión</small></div></div>`;
 if(title==='Compás 4/4 y 16 pasos') return `<div class="note-visual steps-visual">${Array.from({length:16},(_,i)=>`<span class="step ${i%4===0?'beat':''} ${[0,4,8,12].includes(i)?'active-step':''}">${i+1}</span>`).join('')}</div><div class="visual-caption">4 pulsos · 4 subdivisiones por pulso</div>`;
 if(title==='Acordes de séptima') return `<div class="note-visual seventh-visual">${[['maj7','0 · 4 · 7 · 11'],['7','0 · 4 · 7 · 10'],['m7','0 · 3 · 7 · 10']].map(x=>`<div><b>${x[0]}</b><span>${x[1]}</span></div>`).join('')}</div>`;
 return `<div class="note-visual workflow-visual">${['Tonalidad','Acordes','Bajo','Melodía','Ritmo','Arreglo','Mezcla'].map((x,i)=>`<span><b>${i+1}</b>${x}</span>`).join('')}</div>`;
}
function notesPage(){const pdfs=[['acordes_piano.pdf','Acordes de piano','Acordes'],['cadencias_y_funciones.pdf','Cadencias y funciones armónicas','Armonía'],['guia_acordes_y_progresiones.pdf','Guía de acordes y progresiones','Progresiones'],['piano_100_guia.pdf','Piano 100: guía práctica','Fundamentos'],['progresiones_por_genero.pdf','Progresiones por género','Producción']];const map={'Fundamentos':3,'Acordes':0,'Armonía':1,'Progresiones':2,'Producción':4,'Ritmo':4};let cats=['Todas',...new Set(ASTR4_DATA.notes.map(n=>n.category))];let q=state.search.toLowerCase();let notes=ASTR4_DATA.notes.filter(n=>(state.noteCategory==='Todas'||n.category===state.noteCategory)&&(!q||(n.title+n.desc+n.formula).toLowerCase().includes(q)));return `${header('Apuntes','BIBLIOTECA VISUAL')}<section class="wave-banner compact"><img src="assets/onda-astr4.png" alt="Onda sonora violeta de ASTR4"><div><span class="eyebrow">BIBLIOTECA ASTR4</span><h1>La teoría, a primera vista.</h1><p>Esquemas, fórmulas y referencias para consultar mientras estudias o produces.</p></div></section><div class="notes-toolbar"><input class="search" id="note-search" placeholder="Buscar un concepto o apunte…" value="${esc(state.search)}"><span class="notes-count">${notes.length} apuntes</span></div><div class="tabs notes-tabs">${cats.map(c=>`<button class="tab ${state.noteCategory===c?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><div class="notes-grid">${notes.map((n,i)=>{let p=pdfs[map[n.category]??2];return `<article class="note-card note-card-visual"><div class="note-card-top"><span class="pill">${esc(n.category)}</span><span class="note-index">${String(i+1).padStart(2,'0')}</span></div><h3>${esc(n.title)}</h3><p class="note-summary">${esc(n.desc)}</p>${noteVisual(n)}<div class="note-tip"><span class="tip-icon">✦</span><span>${esc(n.tip)}</span></div><a class="btn secondary note-pdf" href="assets/originales/${encodeURIComponent(p[0])}" target="_blank" rel="noopener"><span>Abrir documento original</span><b>↗</b><small>${esc(p[1])}</small></a></article>`}).join('')||'<div class="empty">No se encontraron apuntes.</div>'}</div><div class="section-head documents-heading"><div><div class="eyebrow">FUENTES DE ESTUDIO</div><h2>Documentos originales</h2><p>Consulta el material completo en PDF.</p></div></div><div class="documents-grid">${pdfs.map((p,i)=>`<a class="document-card" href="assets/originales/${encodeURIComponent(p[0])}" target="_blank" rel="noopener"><span class="document-icon">PDF</span><span><b>${esc(p[1])}</b><small>${['Acordes y posiciones','Cadencias y funciones','Armonía y progresiones','Guía práctica de piano','Progresiones por estilos'][i]}</small></span><i>↗</i></a>`).join('')}</div>`}
function activitiesPage(){const activities=[['Piano 100','Práctica progresiva de piano','piano-100.html','PIANO'],['Acordes mayor y menor','Identifica y compara tríadas en el teclado','acordes-mayor-menor.html','ARMONÍA'],['Acordes relámpago','Reconocimiento rápido de acordes','acordes-relampago.html','RETO'],['Círculo de quintas','Explora tonalidades y relaciones','circulo-de-quintas.html','TEORÍA'],['Constructor de progresiones','Crea secuencias armónicas','constructor-de-progresiones.html','CREACIÓN'],['Mapa de progresiones','Explora recorridos armónicos','mapa-de-progresiones.html','ARMONÍA'],['Laboratorio de mezcla','Experimenta con decisiones de mezcla','laboratorio-de-mezcla.html','PRODUCCIÓN'],['Mini estudio de loops','Construye y transforma loops','mini-estudio-de-loops.html','PRODUCCIÓN'],['Melodías tristes y nostálgicas','Practica recursos melódicos y emocionales','melodias-tristes-y-nostalgicas.html','COMPOSICIÓN'],['Repaso total de armonía','Comprueba y refuerza conceptos','repaso-total-de-armonia.html','REPASO']];return `${header('Actividades','PRACTICA · EXPERIMENTA · CONSOLIDA')}<section class="wave-banner"><img src="assets/onda-astr4.png" alt="Onda sonora ASTR4"><div><span class="eyebrow">ZONA DE PRÁCTICA</span><h1>La teoría se demuestra haciendo.</h1><p>Actividades interactivas que se abren dentro de ASTR4, sin perder tu lugar.</p></div></section><div class="activity-grid">${activities.map((a,i)=>`<article class="activity-card"><span class="pill">${a[3]}</span><div class="activity-index">${String(i+1).padStart(2,'0')}</div><h3>${esc(a[0])}</h3><p>${esc(a[1])}</p><a class="btn small" href="./assets/originales/actividades/${a[2]}" data-activity="${a[2]}" target="_blank" rel="noopener">Abrir actividad ↗</a></article>`).join('')}</div><div class="callout" style="margin-top:18px">Las actividades se ejecutan dentro de ASTR4. Si tu navegador bloquea la ventana integrada, el enlace también puede abrirse en una pestaña independiente.</div>`}

function openActivity(filename){const safe=String(filename||'').replace(/[^a-z0-9.-]/gi,'');if(!safe)return;const url=new URL('./assets/originales/actividades/'+safe,document.baseURI).href;document.querySelector('.activity-viewer')?.remove();const overlay=document.createElement('section');overlay.className='activity-viewer';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Actividad musical');overlay.innerHTML=`<header class="activity-viewer-bar"><button type="button" class="activity-viewer-back" aria-label="Volver a actividades">← <span>Volver a ASTR4</span></button><span class="activity-viewer-label">ACTIVIDAD INTERACTIVA</span><a class="activity-viewer-external" href="${url}" target="_blank" rel="noopener">Abrir aparte ↗</a></header><iframe class="activity-viewer-frame" title="Actividad musical ASTR4" src="${url}" allow="autoplay; microphone" loading="eager"></iframe>`;document.body.appendChild(overlay);document.body.classList.add('activity-open');overlay.querySelector('.activity-viewer-back').addEventListener('click',closeActivity);overlay.addEventListener('click',e=>{if(e.target===overlay)closeActivity()});overlay.querySelector('iframe').addEventListener('error',()=>{toast('No se ha podido cargar la actividad. Usa «Abrir aparte».')});history.pushState({astr4Activity:true},'','#actividad');}
function closeActivity(){const el=document.querySelector('.activity-viewer');if(el)el.remove();document.body.classList.remove('activity-open');if(location.hash==='#actividad')history.back();}
window.addEventListener('popstate',()=>{const el=document.querySelector('.activity-viewer');if(el){el.remove();document.body.classList.remove('activity-open')}});

function keyboardHtml(){let white=[0,2,4,5,7,9,11,12,14,16,17,19,21,23];let black=[1,3,6,8,10,13,15,18,20,22];let whites=white.map((n,i)=>`<button class="key" data-note="${n}" aria-label="${NOTES[n%12]}"><small>${NOTES[n%12]}</small></button>`).join('');let blacks=black.map(n=>{let left=(white.findIndex(w=>w>n)/white.length)*100;return `<button class="key black" style="left:${left}%" data-note="${n}" aria-label="${NOTES[n%12]}"><small>${NOTES[n%12]}</small></button>`}).join('');return `<div class="keyboard-wrap"><div class="keyboard">${whites}${blacks}</div></div><div class="keyboard-hint">Teclado adaptable al ancho de tu pantalla. Toca una tecla para escucharla.</div>`}
function lab(){let root=state.root,chord=CHORDS[state.chord]||CHORDS.mayor,tones=chord.map(x=>(root+x)%12),scale=SCALES[state.scale||'Mayor'].map(x=>(root+x)%12);return `${header('Laboratorio musical','EXPERIMENTA Y ESCUCHA')}<div class="tabs"><button class="tab ${state.labTab==='acordes'?'active':''}" data-lab="acordes">Acordes</button><button class="tab ${state.labTab==='escalas'?'active':''}" data-lab="escalas">Escalas</button><button class="tab ${state.labTab==='progresiones'?'active':''}" data-lab="progresiones">Progresiones</button><button class="tab ${state.labTab==='piano'?'active':''}" data-lab="piano">Piano</button></div>${state.labTab==='acordes'?`<div class="card"><div class="field"><label>NOTA FUNDAMENTAL</label><select id="root-select">${NOTES.map((n,i)=>`<option value="${i}" ${i===root?'selected':''}>${n}${ENH[n]?' / '+ENH[n]:''}</option>`).join('')}</select></div><div class="field"><label>TIPO DE ACORDE</label><select id="chord-select">${Object.keys(CHORDS).map(k=>`<option value="${k}" ${state.chord===k?'selected':''}>${({mayor:'Mayor',menor:'Menor',disminuido:'Disminuido',aumentado:'Aumentado',maj7:'Séptima mayor (maj7)','7':'Séptima dominante (7)',m7:'Menor séptima (m7)'})[k]}</option>`).join('')}</select></div><div class="formula">${tones.map(n=>NOTES[n]).join(' · ')}</div><p class="tiny">Notas del acorde. Toca cada una en el teclado para escucharla o reproduce el acorde completo.</p><div class="control-row"><button class="btn" data-action="play-chord">▶ Escuchar acorde</button><button class="btn ghost" data-action="download-chord">Descargar MIDI</button></div></div>${keyboardHtml()}<div class="callout">Consejo: escucha cómo cambia el color al modificar la tercera. Una tríada mayor usa 4 + 3 semitonos; una menor, 3 + 4.</div>`:state.labTab==='escalas'?`<div class="card"><div class="field"><label>TONALIDAD</label><select id="root-select">${NOTES.map((n,i)=>`<option value="${i}" ${i===root?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>TIPO DE ESCALA</label><select id="scale-select">${Object.keys(SCALES).map(k=>`<option ${state.scale===k?'selected':''}>${k}</option>`).join('')}</select></div><div class="formula">${scale.map(n=>NOTES[n]).join(' · ')}</div><button class="btn" data-action="play-scale">▶ Escuchar escala</button></div>${keyboardHtml()}`:state.labTab==='progresiones'?`<div class="list">${PROGS.map((p,i)=>`<div class="list-item" style="display:block"><div class="control-row" style="justify-content:space-between"><span class="pill">${p.vibe}</span><button class="btn small" data-prog="${i}">▶ Escuchar</button></div><strong style="margin-top:8px">${p.name}</strong><p class="tiny">${p.degrees.join(' – ')}</p><div class="formula">${p.chords.join(' → ')}</div></div>`).join('')}</div><div class="callout">Las progresiones son puntos de partida. Cambia el ritmo, las inversiones y la melodía para darles una identidad propia.</div>`:`${keyboardHtml()}<div class="card"><h3>Prueba libre</h3><p class="tiny">Toca las teclas del piano. Puedes usarlo para localizar notas y escuchar alturas.</p></div>`}`}
function ear(){return `${header('Entrenamiento auditivo','ENTRENA TU OÍDO')}<div class="card"><span class="pill">RECONOCIMIENTO DE INTERVALOS</span><h3>¿Qué intervalo has escuchado?</h3><p class="tiny">Pulsa reproducir y compara la distancia entre las dos notas. Se generan tonos con el sintetizador integrado.</p><button class="btn" data-action="ear-play">▶ Reproducir intervalo</button><div class="answer-grid" style="margin-top:12px">${['Segunda mayor','Tercera mayor','Cuarta justa','Quinta justa'].map((n,i)=>`<button class="answer" data-ear="${i}">${n}</button>`).join('')}</div><p id="ear-feedback" class="tiny">Aciertos: ${state.earScore} · Intentos: ${state.earCount}</p><button class="btn ghost small" data-action="ear-new">Nuevo intervalo</button></div><div class="callout" style="margin-top:14px">Consejo: intenta cantar la segunda nota y sentir cuánto se separa de la primera. El oído relativo mejora con práctica frecuente y breve.</div>`}
function dictionary(){let q=state.search.toLowerCase();let items=ASTR4_DATA.glossary.filter(x=>(x[0]+x[1]).toLowerCase().includes(q));return `${header('Diccionario musical','CONSULTA RÁPIDA')}<input class="search" id="dict-search" placeholder="Buscar concepto…" value="${esc(state.search)}" style="margin-bottom:13px"><div class="list">${items.map(x=>`<article class="note-card"><h3>${esc(x[0])}</h3><p class="tiny">${esc(x[1])}</p></article>`).join('')||'<div class="empty">No hay resultados.</div>'}</div>`}
function composition(){return `${header('Academia de composición','DE LA TEORÍA A TU MÚSICA')}<div class="card"><h3>Un método para crear una idea</h3><ol class="lesson-content"><li>Elige una emoción o una referencia sonora.</li><li>Selecciona una tonalidad cómoda para tu voz o instrumento.</li><li>Construye una progresión sencilla de cuatro acordes.</li><li>Define un patrón rítmico y un tempo.</li><li>Escribe un motivo melódico corto con notas del acorde como puntos de apoyo.</li><li>Repite, varía y deja espacio para la voz.</li></ol></div><div class="section-head"><h2>Generador de punto de partida</h2></div><div class="card"><div class="field"><label>ESTILO</label><select id="style-select"><option>Reggaetón melódico</option><option>Trap / R&B</option><option>Pop urbano</option><option>Neo-soul</option><option>EDM</option></select></div><div class="field"><label>EMOCIÓN</label><select id="mood-select"><option>Melancólica</option><option>Enérgica</option><option>Nostálgica</option><option>Oscura</option><option>Esperanzadora</option></select></div><button class="btn" data-action="idea">Generar idea</button><div id="idea-result" class="formula" style="display:none"></div></div><div class="section-head"><h2>Tu cuaderno de ideas</h2></div><div class="card"><div class="field"><label>NUEVA IDEA</label><textarea id="personal-note" placeholder="Anota una melodía, una progresión, una referencia o una idea de producción…"></textarea></div><button class="btn" data-action="save-note">Guardar idea</button>${db.notes.length?`<div class="divider"></div>${db.notes.map((n,i)=>`<div class="note-card" style="margin-top:8px"><p>${esc(n.text)}</p><small class="tiny">${new Date(n.date).toLocaleDateString('es-ES')}</small><button class="btn ghost small" data-delete-note="${i}">Eliminar</button></div>`).join('')}`:''}</div>`}
function tools(){return `${header('Herramientas','UTILIDADES PARA PRODUCIR')}<div class="grid"><div class="card"><span class="card-icon">◷</span><h3>Metrónomo</h3><p>Marca el pulso y practica con BPM ajustables.</p><div class="field"><label>TEMPO · BPM</label><input id="tempo" type="number" min="30" max="240" value="${state.tempo}"></div><div class="control-row"><button class="btn small" data-action="metro-start">▶ Iniciar</button><button class="btn ghost small" data-action="metro-stop">Detener</button></div><div id="metro-beat" class="formula">Pulso detenido</div></div><div class="card"><span class="card-icon">♩</span><h3>Afinador</h3><p>Detecta la frecuencia captada por el micrófono.</p><button class="btn small" data-action="tuner-start">Activar micrófono</button><button class="btn ghost small" data-action="tuner-stop">Detener</button><div id="tuner-result" class="formula">Esperando audio…</div><p class="tiny">El micrófono solo se activa con tu permiso y mientras esta pantalla está abierta.</p></div></div><div class="section-head"><h2>Biblioteca MIDI</h2></div><div class="card"><p class="tiny">Incluye archivos MIDI originales de acordes y progresiones. Descárgalos para abrirlos en Ableton Live u otro DAW.</p><button class="btn secondary" data-go="midi">Explorar archivos MIDI</button></div>`}
function progress(){let done=db.completed.length,all=lessons.length,pct=Math.round(done/all*100);return `${header('Tu progreso','SEGUIMIENTO DE APRENDIZAJE')}<div class="hero"><div class="eyebrow">AVANCE GLOBAL</div><h1>${pct}%</h1><p>Has completado ${done} de ${all} lecciones disponibles en esta versión de ASTR4.</p><div class="progress"><i style="width:${pct}%"></i></div><div class="stat-row"><div class="stat"><strong>${done}</strong><span>Completadas</span></div><div class="stat"><strong>${db.favorites.length}</strong><span>Favoritos</span></div><div class="stat"><strong>${db.notes.length}</strong><span>Ideas guardadas</span></div></div></div><div class="section-head"><h2>Por academia</h2></div><div class="card"><h3>Teoría musical y piano</h3><p>${courseLessons('piano').filter(l=>db.completed.includes(l.id)).length} / ${courseLessons('piano').length}</p><div class="progress"><i style="width:${courseLessons('piano').filter(l=>db.completed.includes(l.id)).length/courseLessons('piano').length*100}%"></i></div><h3 style="margin-top:18px">Producción musical</h3><p>${courseLessons('production').filter(l=>db.completed.includes(l.id)).length} / ${courseLessons('production').length}</p><div class="progress"><i style="width:${courseLessons('production').filter(l=>db.completed.includes(l.id)).length/courseLessons('production').length*100}%"></i></div></div><div class="section-head"><h2>Mis favoritos</h2></div><div class="list">${db.favorites.map(id=>{let l=lessons.find(x=>x.id===id);return l?`<button class="list-item" data-lesson="${id}"><span class="num">★</span><span><strong>${esc(l.title)}</strong><small>${l.course==='piano'?'Teoría y piano':'Producción musical'}</small></span><span class="chev">›</span></button>`:''}).join('')||'<div class="empty">Todavía no has guardado favoritos.</div>'}</div><div class="section-head"><h2>Herramientas de datos</h2></div><div class="card"><p class="tiny">Tus avances, favoritos y notas se guardan en este navegador. No se sincronizan automáticamente entre dispositivos.</p><div class="control-row" style="margin-top:12px"><button class="btn" data-action="backup">Exportar copia</button><button class="btn secondary" data-action="restore">Restaurar copia</button><button class="btn ghost" data-action="reset">Reiniciar progreso</button></div><input type="file" id="restore-file" accept="application/json" hidden></div>`}
function resources(){let root='assets/originales/';let pdf=['acordes_piano.pdf','cadencias_y_funciones.pdf','guia_acordes_y_progresiones.pdf','piano_100_guia.pdf','progresiones_por_genero.pdf'];let html=['Práctica/Piano 100_.html','Práctica/acordes_mayor_menor_piano.html','Práctica/acordes_relampago.html','Práctica/circulo_quintas.html','Práctica/constructor_progresiones.html','Práctica/laboratorio_mezcla.html','Práctica/mapa_del_viaje_progresiones.html','Práctica/mini_estudio_loops.html','Práctica/progresiones_de_acordes.html','Práctica/Melodías tristes y nostálgicas.html','Práctica/Programa de armonía_ repaso total.html'];return `${header('Material original','TU CARPETA INTEGRADA')}<p class="tiny">Los documentos originales se han conservado sin sobrescribirlos. Los PDF se pueden abrir en el navegador; las herramientas HTML originales se mantienen como recursos independientes.</p><div class="section-head"><h2>Documentos PDF</h2></div><div class="list">${pdf.map(f=>`<a class="list-item" href="${urlPath(root+f)}" target="_blank" rel="noopener" style="text-decoration:none"><span class="num">PDF</span><span><strong>${esc(f.replaceAll('_',' ').replace('.pdf',''))}</strong><small>Documento original</small></span><span class="chev">↗</span></a>`).join('')}</div><div class="section-head"><h2>Herramientas HTML originales</h2></div><div class="list">${html.map(f=>`<a class="list-item" href="${urlPath(root+f)}" target="_blank" rel="noopener" style="text-decoration:none"><span class="num">HTML</span><span><strong>${esc(decodeURIComponent(f.split('/').pop().replace('.html','').replaceAll('_',' ')))}</strong><small>Herramienta original</small></span><span class="chev">↗</span></a>`).join('')}</div>`}
async function midiPage(){let files=[];try{let r=await fetch('assets/midi-index.json');files=await r.json()}catch(e){}state.midi=files;return `${header('Biblioteca MIDI','ARCHIVOS PARA TU DAW')}<p class="tiny">${files.length} archivos MIDI originales incluidos. Descarga los acordes individuales y las progresiones organizadas por estilo.</p><input class="search" id="midi-search" placeholder="Buscar archivo, acorde o género…"><div class="list" id="midi-list">${files.map((f,i)=>`<a class="list-item midi-row" data-name="${esc(f.name.toLowerCase())}" href="${urlPath(f.path)}" download style="text-decoration:none"><span class="num">MIDI</span><span><strong>${esc(f.name)}</strong><small>${esc(f.path.split('/').slice(-3,-1).join(' · '))}</small></span><span class="chev">↓</span></a>`).join('')}</div>`}
function productionSuite(){
 const checks=db.productionChecks||{};const groups=[
  ['pre','Preproducción',['Definir emoción y mensaje de la canción','Elegir tonalidad y tempo','Cerrar progresión y melodía principal','Crear estructura completa','Preparar referencias de sonido']],
  ['record','Grabación vocal',['Grabar varias tomas completas','Elegir las mejores frases (comping)','Limpiar respiraciones y ruidos sin cortar de más','Ajustar timing con naturalidad','Grabar dobles y armonías necesarias']],
  ['mix','Mezcla',['Ajustar ganancia antes de procesar','Conseguir balance estático de volúmenes','Revisar relación entre bombo y bajo','Limpiar enmascaramientos con EQ','Controlar dinámica con compresión','Añadir profundidad con envíos','Comprobar mono, fase y panorama','Comparar con referencia al mismo volumen']],
  ['master','Entrega',['Dejar margen de pico antes del limitador','Revisar picos verdaderos y distorsión','Escuchar en auriculares, altavoces y móvil','Exportar WAV de máxima calidad','Guardar instrumental, acapella y stems','Archivar proyecto y copia de seguridad']],
  ['release','Lanzamiento',['Mezcla final aprobada','Master final aprobado','Portada lista y con derechos despejados','Título, créditos y colaboradores revisados','Distribución y fecha de lanzamiento decididas','Canvas / visualizer / contenido promocional preparado','Enlaces y perfiles de artista revisados']]
 ];let total=0,done=0;groups.forEach(([id,,items])=>items.forEach((_,i)=>{total++;if(checks[id+'-'+i])done++}));
 const chain=[['Tune / corrección','Afinación y edición correctiva; evita cuantizar cada nota sin escuchar.'],['EQ sustractiva','Retira resonancias o acumulación que realmente molesten.'],['Compresión 1','Controla picos y estabiliza la interpretación.'],['De-esser','Reduce sibilancias solo cuando sobresalen.'],['Saturación','Añade armónicos con moderación si la voz lo necesita.'],['EQ tonal','Da forma al carácter después de corregir.'],['Compresión 2 (opcional)','Aporta densidad o control adicional si hace falta.'],['Reverb / delay por envíos','Crea profundidad sin lavar la voz directa.'],['Automatización','Ajusta frases, efectos y niveles a lo largo de la canción.']];
 const chosen=db.releaseData?.chain||['Tune / corrección','EQ sustractiva','Compresión 1','De-esser','Reverb / delay por envíos','Automatización'];
 return `${header('Sala de producción','PREPRODUCCIÓN · GRABACIÓN · MEZCLA · LANZAMIENTO')}
 <section class="upgrade-hero"><div><span class="eyebrow">ASTR4 PRODUCTION WORKFLOW</span><h1>De la sesión<br><em>a la entrega.</em></h1><p>Un centro de control para producir con intención: prepara la canción, organiza la grabación, toma decisiones de mezcla y no olvides nada antes de publicar.</p><div class="upgrade-kpis"><div><b>${done}/${total}</b><small>Pasos completados</small></div><div><b>${Math.round(done/total*100)}%</b><small>Flujo completado</small></div><div><b>${groups.filter(([id,,items])=>items.every((_,i)=>checks[id+'-'+i])).length}/5</b><small>Etapas cerradas</small></div></div><div class="upgrade-progress"><i style="width:${done/total*100}%"></i></div></div></section>
 <div class="production-layout"><main>
 <section class="upgrade-panel"><div class="upgrade-title"><div><span class="eyebrow">CONTROL DE CALIDAD</span><h2>Checklist de producción</h2></div><span class="upgrade-tag">${done} / ${total}</span></div><p class="studio-muted">Marca cada punto cuando esté resuelto. El avance se guarda automáticamente en este dispositivo.</p>${groups.map(([id,title,items])=>{let n=items.filter((_,i)=>checks[id+'-'+i]).length;return `<details class="production-stage" ${id==='pre'||id==='mix'?'open':''}><summary><span><b>${title}</b><small>${n}/${items.length} completados</small></span><i>${Math.round(n/items.length*100)}%</i></summary><div class="production-checks">${items.map((x,i)=>`<label class="production-check"><input type="checkbox" data-production-check="${id}-${i}" ${checks[id+'-'+i]?'checked':''}><span>${esc(x)}</span></label>`).join('')}</div></details>`}).join('')}</section>
 <section class="upgrade-panel"><div class="upgrade-title"><div><span class="eyebrow">DISEÑA TU CADENA</span><h2>Cadena vocal orientativa</h2></div><span class="upgrade-tag">NO ES UNA RECETA FIJA</span></div><p class="studio-muted">Selecciona los procesos que necesitas. El orden es una referencia de partida; escucha cada cambio y elimina lo que no aporte.</p><div class="chain-list">${chain.map(([name,desc],i)=>`<label class="chain-item"><input type="checkbox" data-chain="${esc(name)}" ${chosen.includes(name)?'checked':''}><span class="chain-num">${String(i+1).padStart(2,'0')}</span><span><b>${esc(name)}</b><small>${esc(desc)}</small></span></label>`).join('')}</div><div class="callout">Punto de partida para voz urbana: edición → afinación → control dinámico → tono → efectos por envíos → automatización. Ajusta según la toma y el arreglo.</div></section>
 <section class="upgrade-panel"><div class="upgrade-title"><div><span class="eyebrow">BITÁCORA DE MEZCLA</span><h2>Decisiones y revisiones</h2></div></div><form id="production-note-form" class="upgrade-form"><label>Nombre de la canción<input name="track" maxlength="80" placeholder="Ej. Demo 04" required></label><label>Qué he cambiado<textarea name="change" rows="3" placeholder="Ej. He reducido 250 Hz en la voz porque se acumulaba con el piano…" required></textarea></label><label>Qué debo comprobar después<textarea name="next" rows="2" placeholder="Ej. Comparar el estribillo en mono y revisar el delay…"></textarea></label><button class="btn" type="submit">Guardar decisión</button></form>${(db.productionNotes||[]).slice(0,8).map(n=>`<article class="production-note"><div><b>${esc(n.track)}</b><small>${new Date(n.date).toLocaleString('es-ES')}</small></div><p>${esc(n.change)}</p>${n.next?`<small><b>Revisar:</b> ${esc(n.next)}</small>`:''}</article>`).join('')||'<p class="tiny">Todavía no hay decisiones guardadas. Registrar cambios te ayudará a mezclar con criterio y no repetir pruebas.</p>'}</section>
 </main><aside>
 <section class="upgrade-panel"><div class="eyebrow">ENTREGA TÉCNICA</div><h2>Antes de exportar</h2><div class="delivery-spec"><b>Proyecto de trabajo</b><span>Conserva la sesión editable y sus muestras.</span></div><div class="delivery-spec"><b>WAV</b><span>Frecuencia y profundidad acordes al proyecto y al destino. Evita convertir formatos sin necesidad.</span></div><div class="delivery-spec"><b>MP3 / AAC</b><span>Para escucha rápida y compartir demos, no como único máster de archivo.</span></div><div class="delivery-spec"><b>Stems</b><span>Exporta grupos separados cuando los necesites para colaboración o mezcla externa.</span></div><div class="callout">No existe un único valor de LUFS o pico que garantice una buena mezcla en todas las plataformas. Prioriza ausencia de clipping, dinámica adecuada y traducción en distintos sistemas.</div></section>
 <section class="upgrade-panel"><div class="eyebrow">FICHA DE LANZAMIENTO</div><h2>Datos de tu próximo tema</h2><form id="release-form" class="upgrade-form"><label>Título<input name="title" maxlength="90" value="${esc(db.releaseData?.title||'')}" placeholder="Título definitivo"></label><label>Nombre artístico<input name="artist" maxlength="90" value="${esc(db.releaseData?.artist||'')}" placeholder="Artista principal"></label><label>Fecha objetivo<input name="date" type="date" value="${esc(db.releaseData?.date||'')}"></label><label>Distribuidora / destino<input name="distributor" maxlength="90" value="${esc(db.releaseData?.distributor||'')}" placeholder="Por decidir"></label><label>Notas<textarea name="notes" rows="3" placeholder="Créditos, colaboradores, ideas de promoción…">${esc(db.releaseData?.notes||'')}</textarea></label><button class="btn" type="submit">Guardar ficha</button></form><button class="btn secondary studio-wide" data-action="production-export">Exportar informe de producción</button></section>
 </aside></div>`;
}

function render(){document.body.classList.toggle('light-mode',state.theme==='light');document.querySelectorAll('.nav-destination[data-route]').forEach(b=>{const active=b.dataset.route===state.route;b.classList.toggle('current',active);b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false')});document.querySelectorAll('.nav-group').forEach(g=>{const routes=[...g.querySelectorAll('.nav-destination')].map(b=>b.dataset.route);g.classList.toggle('active',routes.includes(state.route));g.querySelectorAll('.nav-destination').forEach(b=>b.classList.toggle('current',b.dataset.route===state.route));});if(state.lesson){view.innerHTML=lessonPage(state.lesson);return}let html='';switch(state.route){case'inicio':html=home();break;case'academia':html=academy();break;case'estudio':html=studio();break;case'produccion':html=productionSuite();break;case'cancionero':html=songbook();break;case'planificador':html=planner();break;case'retos':html=challenges();break;case'curso-piano':html=coursePage('piano');break;case'curso-production':html=coursePage('production');break;case'apuntes':html=notesPage();break;case'actividades':html=activitiesPage();break;case'laboratorio':html=lab();break;case'oido':html=ear();break;case'diccionario':html=dictionary();break;case'composicion':html=composition();break;case'herramientas':html=tools();break;case'progreso':html=progress();break;case'recursos':html=resources();break;case'midi':html='';break;default:html=home()}view.innerHTML=html;if(state.route==='midi')midiPage().then(x=>{if(state.route==='midi')view.innerHTML=x})}
function noteFreq(n,oct=4){return 440*Math.pow(2,((oct-4)*12+n-9)/12)}
function playTone(n,oct=4,dur=.45,when=0){const ctx=audio();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='triangle';osc.frequency.value=noteFreq(n,oct);gain.gain.setValueAtTime(.0001,ctx.currentTime+when);gain.gain.exponentialRampToValueAtTime(.17,ctx.currentTime+when+.015);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+when+dur);osc.connect(gain).connect(ctx.destination);osc.start(ctx.currentTime+when);osc.stop(ctx.currentTime+when+dur+.03)}
let audioCtx;function audio(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx}
function playChord(root,intervals,oct=4){intervals.forEach(n=>playTone((root+n)%12,oct+Math.floor((root+n)/12),1.1,0))}
function downloadMidi(name,notes){ // Genera un MIDI tipo 0 mínimo, 480 PPQ, 1 segundo por nota.
 const vlq=v=>{let b=[v&127];while((v>>=7)){b.unshift((v&127)|128)}return b};let ev=[];let tick=0;notes.forEach(n=>{ev.push(...vlq(0),0x90,n,90);ev.push(...vlq(480),0x80,n,0)});ev.push(0,0xff,0x2f,0);let len=ev.length;let bytes=[0x4d,0x54,0x68,0x64,0,0,0,6,0,0,0,1,1,0xe0,0x4d,0x54,0x72,0x6b,(len>>>24)&255,(len>>>16)&255,(len>>>8)&255,len&255,...ev];let blob=new Blob([new Uint8Array(bytes)],{type:'audio/midi'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name+'.mid';a.click();URL.revokeObjectURL(a.href);toast('Archivo MIDI generado')}
function markComplete(id){if(!db.completed.includes(id))db.completed.push(id);db.lastStudy=lessons.find(l=>l.id===id)?.title||db.lastStudy;save();toast('Progreso guardado');render()}
function answerQuiz(btn){let right=Number(btn.dataset.correct),chosen=Number(btn.dataset.quiz);document.querySelectorAll('[data-quiz]').forEach(b=>b.disabled=true);btn.classList.add(chosen===right?'correct':'wrong');document.querySelectorAll('[data-quiz]')[right].classList.add('correct');$('#quiz-feedback').textContent=chosen===right?'¡Correcto! Buen trabajo.':'No exactamente. La respuesta correcta está marcada en verde. Revisa el ejemplo y vuelve a intentarlo más adelante.';}
function newEar(){let intervals=[2,4,5,7],names=['Segunda mayor','Tercera mayor','Cuarta justa','Quinta justa'];let i=Math.floor(Math.random()*4);state.ear={i,interval:intervals[i]};return state.ear}
function earPlay(){let e=state.ear||newEar();playTone(0,4,.55,0);playTone(e.interval,4,.55,.65)}
let tunerStream,tunerFrame;
function tunerStart(){navigator.mediaDevices?.getUserMedia({audio:true}).then(stream=>{tunerStream=stream;const ctx=audio(),src=ctx.createMediaStreamSource(stream),an=ctx.createAnalyser();an.fftSize=2048;src.connect(an);const buf=new Float32Array(an.fftSize);const detect=()=>{an.getFloatTimeDomainData(buf);let rms=Math.sqrt(buf.reduce((s,x)=>s+x*x,0)/buf.length);if(rms>.01){let best=0,max=0;for(let lag=40;lag<1000;lag++){let sum=0;for(let j=0;j<buf.length-lag;j++)sum+=buf[j]*buf[j+lag];if(sum>max){max=sum;best=lag}}let hz=ctx.sampleRate/best;if(hz>40&&hz<1000){let midi=Math.round(69+12*Math.log2(hz/440)),name=NOTES[(midi%12+12)%12],target=440*Math.pow(2,(midi-69)/12),cents=Math.round(1200*Math.log2(hz/target));$('#tuner-result').textContent=`${name} · ${hz.toFixed(1)} Hz · ${cents>0?'+':''}${cents} cents`}}tunerFrame=requestAnimationFrame(detect)};detect();$('#tuner-result').textContent='Escuchando…'}).catch(()=>toast('No se pudo acceder al micrófono. Comprueba los permisos y usa HTTPS.'))}
function tunerStop(){if(tunerFrame)cancelAnimationFrame(tunerFrame);if(tunerStream)tunerStream.getTracks().forEach(t=>t.stop());tunerStream=null;let el=$('#tuner-result');if(el)el.textContent='Micrófono detenido'}
function metroStart(){metroStop();state.tempo=Math.min(240,Math.max(30,Number($('#tempo')?.value)||100));let interval=60000/state.tempo;state.beat=0;const tick=()=>{state.beat=state.beat%4+1;let el=$('#metro-beat');if(el)el.textContent=`Pulso ${state.beat} de 4`;playTone(state.beat===1?0:7,5,.07)};tick();state.metronome=setInterval(tick,interval)}function metroStop(){if(state.metronome)clearInterval(state.metronome);state.metronome=null;let el=$('#metro-beat');if(el)el.textContent='Pulso detenido'}
function backup(){let payload={format:'ASTR4-backup',version:1,exportedAt:new Date().toISOString(),data:db};let blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='astr4-copia-seguridad-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(a.href);toast('Copia de seguridad exportada')}
function restore(file){let r=new FileReader();r.onload=()=>{try{let obj=JSON.parse(r.result);if(obj.format!=='ASTR4-backup'||!obj.data)throw Error();db={...db,...obj.data};save();toast('Copia restaurada correctamente');render()}catch(e){toast('El archivo no es una copia válida de ASTR4')}};r.readAsText(file)}
// Audio móvil/iOS: desbloquea Web Audio directamente dentro del gesto táctil y reproduce en pointerdown.
view.addEventListener('pointerdown',e=>{const key=e.target.closest('[data-note]');if(!key)return;e.preventDefault();const n=Number(key.dataset.note);try{const ctx=audio();if(ctx.state==='suspended')ctx.resume();playTone(n%12,4+Math.floor(n/12),.55);key.classList.add('active');setTimeout(()=>key.classList.remove('active'),260);}catch(err){toast('Toca de nuevo para activar el audio en Safari.');}},{passive:false});
view.addEventListener('submit',e=>{if(e.target.id==='song-form'){e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')||'').trim();if(!title){toast('Escribe un título');return;}db.songs=db.songs||[];db.songs.unshift({id:'song-'+Date.now(),title,status:String(f.get('status')||'Idea'),genre:String(f.get('genre')||''),mood:String(f.get('mood')||''),key:String(f.get('key')||''),bpm:Math.max(40,Math.min(220,Number(f.get('bpm'))||95)),concept:String(f.get('concept')||'').trim(),lyrics:String(f.get('lyrics')||'').trim(),structure:String(f.get('structure')||'').trim(),production:String(f.get('production')||'').trim(),created:new Date().toISOString()});save();render();toast('Canción guardada en tu cuaderno');return;}if(e.target.id==='production-note-form'){e.preventDefault();const f=new FormData(e.target);db.productionNotes=db.productionNotes||[];db.productionNotes.unshift({track:String(f.get('track')||'').trim(),change:String(f.get('change')||'').trim(),next:String(f.get('next')||'').trim(),date:new Date().toISOString()});save();render();toast('Decisión de mezcla guardada');return;}if(e.target.id==='release-form'){e.preventDefault();const f=new FormData(e.target);db.releaseData={...(db.releaseData||{}),title:String(f.get('title')||''),artist:String(f.get('artist')||''),date:String(f.get('date')||''),distributor:String(f.get('distributor')||''),notes:String(f.get('notes')||''),chain:db.releaseData?.chain||[]};save();toast('Ficha de lanzamiento guardada');return;}if(e.target.id!=='studio-project-form')return;e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim();if(!name){toast('Escribe un nombre');return;}db.projects=db.projects||[];db.projects.unshift({id:'project-'+Date.now(),name,style:String(f.get('style')||''),mood:String(f.get('mood')||''),key:String(f.get('key')||''),bpm:Math.max(40,Math.min(220,Number(f.get('bpm'))||95)),notes:String(f.get('notes')||'').trim(),created:new Date().toISOString()});save();render();toast('Proyecto guardado en este dispositivo');});
view.addEventListener('change',e=>{if(e.target.matches('[data-production-check]')){db.productionChecks=db.productionChecks||{};db.productionChecks[e.target.dataset.productionCheck]=e.target.checked;save();const details=e.target.closest('.production-stage');if(details){const all=details.querySelectorAll('[data-production-check]'),n=[...all].filter(x=>x.checked).length;details.querySelector('summary i').textContent=Math.round(n/all.length*100)+'%';details.querySelector('summary small').textContent=n+'/'+all.length+' completados';}const all=document.querySelectorAll('[data-production-check]'),n=[...all].filter(x=>x.checked).length;const hero=document.querySelector('.upgrade-hero');if(hero){hero.querySelector('.upgrade-kpis b').textContent=n+'/'+all.length;hero.querySelectorAll('.upgrade-kpis b')[1].textContent=Math.round(n/all.length*100)+'%';hero.querySelector('.upgrade-progress i').style.width=(n/all.length*100)+'%';}return;}if(e.target.matches('[data-chain]')){db.releaseData=db.releaseData||{};let a=db.releaseData.chain||['Tune / corrección','EQ sustractiva','Compresión 1','De-esser','Reverb / delay por envíos','Automatización'];a=e.target.checked?[...new Set([...a,e.target.dataset.chain])]:a.filter(x=>x!==e.target.dataset.chain);db.releaseData.chain=a;save();return;}if(e.target.matches('[data-plan-day][data-plan-task]')){const d=e.target.dataset.planDay,k=e.target.dataset.planTask;db.weeklyPlan=db.weeklyPlan||{};db.weeklyPlan[d]=db.weeklyPlan[d]||{};db.weeklyPlan[d][k]=e.target.checked;save();const el=e.target.closest('.week-day-head')?.querySelector('span');if(el){const n=[...e.target.closest('.week-day').querySelectorAll('input:checked')].length;el.textContent=n+'/5';}const hero=document.querySelector('.planner-hero');if(hero){const all=document.querySelectorAll('[data-plan-day]').length,done=document.querySelectorAll('[data-plan-day]:checked').length;hero.querySelector('.upgrade-kpis b').textContent=done+'/'+all;hero.querySelectorAll('.upgrade-kpis b')[1].textContent=Math.round(done/all*100)+'%';hero.querySelector('.upgrade-progress i').style.width=(done/all*100)+'%';}return;}if(e.target.matches('[data-challenge]')){db.challengeChecks=db.challengeChecks||{};db.challengeChecks[e.target.dataset.challenge]=e.target.checked;save();render();return;}if(e.target.matches('[data-song-status]')){const song=(db.songs||[]).find(x=>x.id===e.target.dataset.songStatus);if(song){song.status=e.target.value;save();toast('Estado actualizado');render();}return;}if(e.target.matches('[data-studio-task]')){const d=new Date().toISOString().slice(0,10);db.practiceChecks=db.practiceChecks||{};db.practiceChecks[d]=db.practiceChecks[d]||{};db.practiceChecks[d][e.target.dataset.studioTask]=e.target.checked;save();toast('Práctica actualizada');}});
view.addEventListener('click',e=>{let b=e.target.closest('button,a');if(!b)return;if(b.dataset.activity){e.preventDefault();openActivity(b.dataset.activity);return;}if(b.dataset.go){go(b.dataset.go);return}if(b.dataset.route){go(b.dataset.route);return}if(b.dataset.lesson!==undefined){let l=lessons.find(x=>x.id===b.dataset.lesson);if(l){state.lesson=l;render();window.scrollTo(0,0)}return}if(b.dataset.category){state.noteCategory=b.dataset.category;render();return}if(b.dataset.lab){state.labTab=b.dataset.lab;render();return}if(b.dataset.quiz!==undefined){answerQuiz(b);return}if(b.dataset.note!==undefined){let n=Number(b.dataset.note);b.classList.add('active');playTone(n%12,4+Math.floor(n/12));setTimeout(()=>b.classList.remove('active'),300);return}if(b.dataset.prog!==undefined){let p=PROGS[Number(b.dataset.prog)];p.roots.forEach((n,i)=>playChord(n,[0,4,7],4+i*0.01));return}if(b.dataset.ear!==undefined){if(!state.ear)state.ear=newEar();let correct=Number(b.dataset.ear)===state.ear.i;state.earCount++;if(correct)state.earScore++;$('#ear-feedback').textContent=`${correct?'¡Correcto!':'No era ese intervalo.'} Aciertos: ${state.earScore} · Intentos: ${state.earCount}`;document.querySelectorAll('[data-ear]').forEach(x=>{x.disabled=true;if(Number(x.dataset.ear)===state.ear.i)x.classList.add('correct')});return}if(b.dataset.deleteNote!==undefined){db.notes.splice(Number(b.dataset.deleteNote),1);save();render();return}if(b.dataset.action){let a=b.dataset.action;switch(a){case'song-delete':{if(confirm('¿Eliminar esta canción del cuaderno?')){db.songs=(db.songs||[]).filter(x=>x.id!==b.dataset.id);save();render();toast('Canción eliminada')}break}case'studio-delete':{if(confirm('¿Eliminar este proyecto?')){db.projects=(db.projects||[]).filter(p=>p.id!==b.dataset.id);save();render();toast('Proyecto eliminado')}break}case'production-export':{const lines=['ASTR4 · INFORME DE PRODUCCIÓN','',`Canción: ${db.releaseData?.title||'Sin título'}`,`Artista: ${db.releaseData?.artist||'Sin indicar'}`,`Fecha objetivo: ${db.releaseData?.date||'Sin indicar'}`,`Destino: ${db.releaseData?.distributor||'Sin indicar'}`,'','CADENA VOCAL SELECCIONADA',...(db.releaseData?.chain||[]).map((x,i)=>`${i+1}. ${x}`),'','CHECKLIST'];const labels={pre:'Preproducción',record:'Grabación vocal',mix:'Mezcla',master:'Entrega',release:'Lanzamiento'};Object.entries(labels).forEach(([id,label])=>{lines.push('',label);const groups={pre:['Definir emoción y mensaje de la canción','Elegir tonalidad y tempo','Cerrar progresión y melodía principal','Crear estructura completa','Preparar referencias de sonido'],record:['Grabar varias tomas completas','Elegir las mejores frases (comping)','Limpiar respiraciones y ruidos sin cortar de más','Ajustar timing con naturalidad','Grabar dobles y armonías necesarias'],mix:['Ajustar ganancia antes de procesar','Conseguir balance estático de volúmenes','Revisar relación entre bombo y bajo','Limpiar enmascaramientos con EQ','Controlar dinámica con compresión','Añadir profundidad con envíos','Comprobar mono, fase y panorama','Comparar con referencia al mismo volumen'],master:['Dejar margen de pico antes del limitador','Revisar picos verdaderos y distorsión','Escuchar en auriculares, altavoces y móvil','Exportar WAV de máxima calidad','Guardar instrumental, acapella y stems','Archivar proyecto y copia de seguridad'],release:['Mezcla final aprobada','Master final aprobado','Portada lista y con derechos despejados','Título, créditos y colaboradores revisados','Distribución y fecha de lanzamiento decididas','Canvas / visualizer / contenido promocional preparado','Enlaces y perfiles de artista revisados']}[id];groups.forEach((x,i)=>lines.push(`${db.productionChecks?.[id+'-'+i]?'[x]':'[ ]'} ${x}`));});lines.push('','NOTAS',db.releaseData?.notes||'');const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ASTR4-informe-produccion.txt';a.click();URL.revokeObjectURL(a.href);toast('Informe exportado');break;}case'studio-log':{const n=Math.max(1,Math.min(600,Number($('#studio-minutes')?.value)||30));db.practiceLog=db.practiceLog||[];db.practiceLog.push({date:new Date().toISOString().slice(0,10),minutes:n,created:new Date().toISOString()});save();render();toast('Sesión registrada');break}case'course':go(b.dataset.course==='piano'?'curso-piano':'curso-production');break;case'continue':state.lesson=lessons.find(l=>!db.completed.includes(l.id))||lessons[0];render();break;case'back-course':go(b.dataset.course==='piano'?'curso-piano':'curso-production');break;case'complete':markComplete(b.dataset.id);break;case'favorite':{let id=b.dataset.id;db.favorites=db.favorites.includes(id)?db.favorites.filter(x=>x!==id):[...db.favorites,id];save();toast('Favoritos actualizados');render();break}case'play-chord':playChord(state.root,CHORDS[state.chord]);break;case'download-chord':downloadMidi('ASTR4-'+NOTES[state.root]+'-'+state.chord,CHORDS[state.chord].map(n=>60+state.root+n));break;case'play-scale':(SCALES[state.scale||'Mayor']).forEach((n,i)=>playTone((state.root+n)%12,4,.25,i*.28));break;case'ear-play':earPlay();break;case'ear-new':state.ear=newEar();earPlay();document.querySelectorAll('[data-ear]').forEach(x=>{x.disabled=false;x.classList.remove('correct','wrong')});$('#ear-feedback').textContent='Nuevo intervalo. Escucha con atención.';break;case'metro-start':metroStart();break;case'metro-stop':metroStop();break;case'tuner-start':tunerStart();break;case'tuner-stop':tunerStop();break;case'backup':backup();break;case'restore':$('#restore-file').click();break;case'reset':if(confirm('¿Seguro que quieres reiniciar el progreso, favoritos y notas guardadas? Exporta antes una copia si quieres conservarlos.')){db={completed:[],favorites:[],notes:[],quiz:{},streak:0,lastStudy:null};save();render()}break;case'idea':{let style=$('#style-select').value,mood=$('#mood-select').value;let p=mood==='Melancólica'?PROGS[1]:mood==='Oscura'?PROGS[3]:mood==='Enérgica'?PROGS[0]:mood==='Nostálgica'?PROGS[1]:PROGS[2];let el=$('#idea-result');el.style.display='block';el.innerHTML=`<strong>${esc(style)} · ${esc(mood)}</strong><br>${p.chords.join(' → ')}<br><small>${p.degrees.join(' – ')} · Punto de partida, no receta fija.</small>`;break}case'save-note':{let text=$('#personal-note').value.trim();if(text){db.notes.unshift({text,date:new Date().toISOString()});save();toast('Idea guardada');render()}break}default:break}}});
view.addEventListener('change',e=>{if(e.target.id==='root-select'){state.root=Number(e.target.value);render()}if(e.target.id==='chord-select'){state.chord=e.target.value;render()}if(e.target.id==='scale-select'){state.scale=e.target.value;render()}if(e.target.id==='restore-file'&&e.target.files[0])restore(e.target.files[0])});
view.addEventListener('input',e=>{if(e.target.id==='course-search'){let q=e.target.value.trim().toLocaleLowerCase('es');document.querySelectorAll('[data-course-title]').forEach(row=>row.style.display=row.dataset.courseTitle.includes(q)?'flex':'none');document.querySelectorAll('.course-unit').forEach(group=>{let visible=[...group.querySelectorAll('[data-course-title]')].some(row=>row.style.display!=='none');group.style.display=visible?'block':'none';if(q&&visible)group.open=true;});}if(e.target.id==='note-search'){state.search=e.target.value;let pos=e.target.selectionStart;render();let n=$('#note-search');n.focus();n.setSelectionRange(pos,pos)}if(e.target.id==='dict-search'){state.search=e.target.value;let pos=e.target.selectionStart;render();let n=$('#dict-search');n.focus();n.setSelectionRange(pos,pos)}if(e.target.id==='midi-search'){let q=e.target.value.toLowerCase();document.querySelectorAll('.midi-row').forEach(r=>r.style.display=r.dataset.name.includes(q)?'flex':'none')}});
$('#themeBtn').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('astr4-theme',state.theme);render()});document.querySelectorAll('.nav-group-trigger').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();const group=b.closest('.nav-group');const opening=!group.classList.contains('open');document.querySelectorAll('.nav-group').forEach(g=>{g.classList.remove('open');g.querySelector('.nav-group-trigger')?.setAttribute('aria-expanded','false')});if(opening){group.classList.add('open');b.setAttribute('aria-expanded','true')}}));document.querySelectorAll('.nav-destination').forEach(b=>b.addEventListener('click',()=>go(b.dataset.route)));document.addEventListener('click',e=>{if(!e.target.closest('.bottom-nav'))document.querySelectorAll('.nav-group').forEach(g=>{g.classList.remove('open');g.querySelector('.nav-group-trigger')?.setAttribute('aria-expanded','false')})});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.nav-group').forEach(g=>{g.classList.remove('open');g.querySelector('.nav-group-trigger')?.setAttribute('aria-expanded','false')})});
window.addEventListener('beforeunload',()=>{metroStop();tunerStop()});if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
render();
})();
